<?php declare(strict_types=1); $canWrite = pl_can_write($company) && !pl_demo_enabled(); ?>
<div class="page-wrap financial-report bank-reconciliation">
    <div class="page-heading"><div><p class="eyebrow">Cash and bank</p><h1>Bank reconciliation</h1><p class="muted">Compare a statement with posted bank entries in <?= pl_e($company['currency']) ?>.</p></div><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation')) ?>">Statement history</a></div>
    <?php if ($form['message']): ?><div class="alert" role="alert" tabindex="-1" data-form-error><?= pl_e($form['message']) ?></div><?php endif; ?>
    <?php if (pl_demo_enabled()): ?><div class="alert">Bank imports and reconciliation changes are disabled in the public sample.</div><?php endif; ?>
    <?php if ($preview): $data = $preview['preview']['data']; ?>
        <?php foreach ($accounts as $account): ?><?php if ((int) $account['id'] === $data['account_id']): ?><p><strong>Selected account:</strong> <?= pl_e($account['code'] . ' · ' . $account['name']) ?> · <?= pl_e($company['currency']) ?></p><?php endif; ?><?php endforeach; ?>
        <section class="panel"><p class="eyebrow">Review before importing</p><h2><?= pl_e($data['reference']) ?></h2><p><?= pl_e(pl_date_label($data['start_date'])) ?> – <?= pl_e(pl_date_label($data['end_date'])) ?> · <?= count($data['rows']) ?> transactions</p><p>Opening <?= pl_e(pl_money($data['opening_balance'])) ?> → closing <?= pl_e(pl_money($data['closing_balance'])) ?>. The statement totals balance.</p><p class="muted">Imported rows are retained as supplied. Check the bank account, dates, references and amounts before confirming.</p>
        <div class="table-wrap"><table class="data-table"><caption class="sr-only">Statement import preview</caption><thead><tr><th>Date</th><th>Reference / description</th><th class="amount">Money in</th><th class="amount">Money out</th></tr></thead><tbody><?php foreach ($data['rows'] as $row): ?><tr><td><?= pl_e($row['date']) ?></td><td><?= pl_e($row['reference']) ?><br><span class="muted"><?= pl_e($row['description']) ?></span></td><td class="amount"><?= pl_e(pl_money($row['money_in'])) ?></td><td class="amount"><?= pl_e(pl_money($row['money_out'])) ?></td></tr><?php endforeach; ?></tbody></table></div>
        <form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="import"><input type="hidden" name="preview_key" value="<?= pl_e($preview['key']) ?>"><button class="button primary">Confirm statement import</button></form></section>
    <?php endif; ?>
    <?php if ($statement): ?>
        <section class="panel"><div class="page-heading"><div><h2><?= pl_e($statement['reference']) ?></h2><p><?= pl_e($statement['account_code'] . ' · ' . $statement['account_name']) ?> · <?= pl_e($statement['start_date']) ?> – <?= pl_e($statement['end_date']) ?></p></div><span class="badge <?= $statement['status'] === 'completed' ? 'posted' : 'draft' ?>"><?= pl_e(['draft' => 'In progress', 'completed' => 'Completed', 'cancelled' => 'Cancelled'][$statement['status']]) ?></span></div>
        <p class="small muted">Imported <time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $statement['imported_at']) . 'Z') ?>"><?= pl_e($statement['imported_at']) ?> UTC</time> by user <?= (int) $statement['imported_by'] ?>. Initial cleared baseline: <?= pl_e(pl_money((string) $statement['baseline_balance'])) ?> before <?= pl_e($statement['baseline_date']) ?>.</p>
        <?php if ($statement['status'] === 'cancelled'): ?><div class="alert"><strong>Cancelled import.</strong> <?= pl_e($statement['cancellation_reason']) ?><br>Cancelled <time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $statement['cancelled_at']) . 'Z') ?>"><?= pl_e($statement['cancelled_at']) ?> UTC</time> by user <?= (int) $statement['cancelled_by'] ?>. Original statement rows remain below. <a href="<?= pl_e(pl_url('/bank-reconciliation')) ?>">Import a corrected statement</a>.</div><?php endif; ?>
        <?php if ($statement['status'] === 'completed'): ?><p>Completed <time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $statement['completed_at']) . 'Z') ?>"><?= pl_e($statement['completed_at']) ?> UTC</time> by user <?= (int) $statement['completed_by'] ?>. Recorded ledger balance <?= pl_e(pl_money((string) $statement['ledger_balance'])) ?>; recorded outstanding <?= pl_e(pl_money((string) $statement['outstanding_balance'])) ?>.</p><?php endif; ?>
        <div class="table-wrap"><table class="data-table"><caption class="sr-only">Reconciliation totals</caption><tbody><tr><th>Statement closing balance</th><td class="amount"><?= pl_e(pl_money((string) $statement['closing_balance'])) ?></td></tr><tr><th>Plus outstanding ledger entries (<?= $summary['outstanding_count'] ?>)</th><td class="amount"><?= pl_e(pl_money($summary['outstanding_balance'])) ?></td></tr><tr><th>Adjusted statement balance</th><td class="amount"><?= pl_e(pl_money($summary['adjusted_statement_balance'])) ?></td></tr><tr><th>Posted ledger balance through statement end</th><td class="amount"><?= pl_e(pl_money($summary['ledger_balance'])) ?></td></tr><tr><th>Difference</th><td class="amount"><strong><?= pl_e(pl_money($summary['difference'])) ?></strong></td></tr></tbody></table></div>
        <p class="muted small">Outstanding entries are posted deposits or payments through the statement end that have not cleared this or an earlier statement. Add their signed net amount to the bank closing balance to compare with the ledger. Every bank row must be matched even when the difference is zero. Reconciliation creates no journal entries.</p>
        <?php if (!$summary['baseline_unchanged']): ?><div class="alert" role="alert">The ledger before the initial statement start changed. Resolve the baseline before completion.</div><?php endif; ?>
        <p><a href="<?= pl_e(pl_url('/reports/account', ['id' => (int) $statement['account_id'], 'as_of' => $statement['end_date']])) ?>">Review bank account activity</a> · <?= $summary['unmatched_count'] ?> unmatched statement rows</p>
        <div class="table-wrap"><table class="data-table"><caption class="sr-only">Bank statement rows and journal matches</caption><thead><tr><th>Date</th><th>Reference / description</th><th class="amount">Money in</th><th class="amount">Money out</th><th>Journal match</th></tr></thead><tbody><?php foreach ($statement['rows'] as $row): ?><tr><td><?= pl_e($row['transaction_date']) ?></td><td><?= pl_e($row['reference']) ?><br><span class="muted"><?= pl_e($row['description']) ?></span></td><td class="amount"><?= pl_e(pl_money((string) $row['money_in'])) ?></td><td class="amount"><?= pl_e(pl_money((string) $row['money_out'])) ?></td><td><?php if ($row['journal_line_id'] !== null): ?><a href="<?= pl_e(pl_url('/journals/detail', ['id' => (int) $row['journal_id']])) ?>">Journal <?= (int) $row['journal_id'] ?> · line <?= (int) $row['journal_line_id'] ?></a><br><span class="muted small"><?= pl_e($row['journal_date']) ?></span><?php if ($canWrite && $statement['status'] === 'draft'): ?><form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="unmatch"><input type="hidden" name="statement_id" value="<?= (int) $statement['id'] ?>"><input type="hidden" name="row_id" value="<?= (int) $row['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $statement['revision'] ?>"><button class="button">Remove match</button></form><?php endif; ?><?php elseif ($canWrite && $statement['status'] === 'draft'): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $statement['id'], 'row' => (int) $row['id']])) ?>#match-review">Review matches</a><?php else: ?>Unmatched<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
        <?php if ($statement['rows'] === []): ?><p>No bank transactions on this statement.</p><?php endif; ?>
        </section>
        <?php if ($summary['outstanding_count'] > 0): ?><section class="panel" id="outstanding"><h2>Outstanding ledger entries</h2><p class="muted">These entries were not matched to this or an earlier statement. They remain available to match when they clear a later statement.</p><div class="table-wrap"><table class="data-table"><caption class="sr-only">Outstanding bank ledger entries</caption><thead><tr><th>Date</th><th>Source</th><th class="amount">Deposit</th><th class="amount">Payment</th></tr></thead><tbody><?php foreach (array_slice($outstandingLines, 0, 50) as $entry): ?><tr><td><?= pl_e($entry['journal_date']) ?></td><td><a href="<?= pl_e(pl_url('/journals/detail', ['id' => (int) $entry['journal_id']])) ?>"><?= pl_e($entry['source_reference']) ?> · Journal <?= (int) $entry['journal_id'] ?> / line <?= (int) $entry['id'] ?></a><br><?= pl_e($entry['description']) ?></td><td class="amount"><?= pl_e(pl_money((string) $entry['debit'])) ?></td><td class="amount"><?= pl_e(pl_money((string) $entry['credit'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if ($outstandingPage > 1): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $statement['id'], 'outstanding_page' => $outstandingPage - 1])) ?>#outstanding">Previous outstanding entries</a><?php endif; ?><?php if (count($outstandingLines) > 50): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $statement['id'], 'outstanding_page' => $outstandingPage + 1])) ?>#outstanding">More outstanding entries</a><?php endif; ?></section><?php endif; ?>
        <?php if ($selectedRow && $canWrite && $statement['status'] === 'draft'): ?><section class="panel" id="match-review"><h2>Review matches for <?= pl_e($selectedRow['reference']) ?></h2><p><?= pl_e($selectedRow['transaction_date']) ?> · <?= pl_e($selectedRow['description']) ?></p><p class="muted">Suggestions have the exact signed amount and are ordered by the nearest posting date. Verify the source and date; no suggestion is accepted automatically. Older entries may be outstanding payments or deposits.</p><?php if (count($candidates) > 1): ?><div class="alert">Multiple candidates have the same amount. Choose only the entry supported by your statement and source record.</div><?php endif; ?><?php if ($candidates === []): ?><p>No unused exact-amount entries are available. Review the account activity and record missing transactions through the normal posting workflow before matching.</p><?php else: ?><form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="match"><input type="hidden" name="statement_id" value="<?= (int) $statement['id'] ?>"><input type="hidden" name="row_id" value="<?= (int) $selectedRow['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $statement['revision'] ?>"><label class="field">Journal entry to match<select name="line_id" required><option value="">Choose after reviewing the source</option><?php foreach (array_slice($candidates, 0, 100) as $candidate): ?><option value="<?= (int) $candidate['id'] ?>"><?= pl_e($candidate['journal_date'] . ' · Journal ' . $candidate['journal_id'] . ' / line ' . $candidate['id'] . ' · ' . $candidate['source_reference'] . ' · ' . $candidate['description']) ?></option><?php endforeach; ?></select></label><button class="button primary">Confirm this match</button></form><?php if (count($candidates) > 100): ?><p>Showing 100 candidates on this page. Continue to more candidates to review other possible sources.</p><?php endif; ?><?php endif; ?></section><?php endif; ?>
        <?php if ($selectedRow && $canWrite && $statement['status'] === 'draft'): ?><p><?php if ($candidatePage > 1): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $statement['id'], 'row' => (int) $selectedRow['id'], 'candidate_page' => $candidatePage - 1])) ?>#match-review">Previous candidates</a><?php endif; ?><?php if (count($candidates) > 100): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $statement['id'], 'row' => (int) $selectedRow['id'], 'candidate_page' => $candidatePage + 1])) ?>#match-review">More candidates</a><?php endif; ?></p><?php endif; ?>
        <?php if ($canWrite && $statement['status'] === 'draft'): ?><section class="panel"><h2>Complete reconciliation</h2><p>Completion freezes this statement and prevents new entries in this bank account on or before <?= pl_e($statement['end_date']) ?>. Corrections need a later date.</p><form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="complete"><input type="hidden" name="statement_id" value="<?= (int) $statement['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $statement['revision'] ?>"><input type="hidden" name="completion_key" value="bank:<?= (int) $statement['id'] ?>:complete:<?= (int) $statement['revision'] ?>"><label><input type="checkbox" name="review_confirmed" value="1" required> I reviewed every match and the outstanding ledger entries.</label><p><button class="button primary" <?= !$summary['ready'] ? 'disabled' : '' ?>>Confirm reconciliation</button></p></form></section><?php endif; ?>
        <?php if ($canWrite && $statement['status'] === 'draft'): ?><details class="panel"><summary>Cancel an incorrect import</summary><p>Remove any saved matches first, then explain the correction. Cancellation retains the original statement, rows and match audit. You can import corrected data using the same bank references.</p><form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="statement_id" value="<?= (int) $statement['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $statement['revision'] ?>"><input type="hidden" name="cancellation_key" value="bank:<?= (int) $statement['id'] ?>:cancel:<?= (int) $statement['revision'] ?>"><label class="field">Reason for cancelling<textarea name="reason" required maxlength="400" rows="3"><?= pl_e(pl_web_text($input, 'reason')) ?></textarea></label><button class="button" <?= count($statement['rows']) !== $summary['unmatched_count'] ? 'disabled' : '' ?>>Cancel draft statement</button></form></details><?php endif; ?>
    <?php else: ?>
        <?php if ($canWrite): ?><section class="panel"><h2>Import a bank statement</h2><p class="muted">Use UTF-8 CSV with up to 500 transactions and 512 KiB. Exact headers: <code>date,reference,description,money_in,money_out</code>. Use YYYY-MM-DD dates, decimal points and 0 for the unused amount column. Each bank transaction needs a durable reference unique across statements for this account.</p>
        <form method="post" enctype="multipart/form-data" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="preview"><input type="hidden" name="MAX_FILE_SIZE" value="524288"><div class="form-grid"><label class="field">Cash / bank account<select name="account_id" required><option value="">Choose account</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account['id'] ?>" <?= (int) ($input['account_id'] ?? 0) === (int) $account['id'] ? 'selected' : '' ?>><?= pl_e($account['code'] . ' · ' . $account['name']) ?></option><?php endforeach; ?></select></label><label class="field">Statement reference<input name="reference" maxlength="120" value="<?= pl_e(pl_web_text($input, 'reference')) ?>" required></label><label class="field">Start date<input type="date" name="start_date" value="<?= pl_e(pl_web_text($input, 'start_date')) ?>" required></label><label class="field">End date<input type="date" name="end_date" value="<?= pl_e(pl_web_text($input, 'end_date')) ?>" required></label><label class="field">Opening balance<input name="opening_balance" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'opening_balance', '0')) ?>" required></label><label class="field">Closing balance<input name="closing_balance" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'closing_balance')) ?>" required></label><label class="field full-width">Paste CSV<textarea name="csv" rows="7" maxlength="524288" placeholder="date,reference,description,money_in,money_out"><?= pl_e(pl_web_text($input, 'csv')) ?></textarea></label><label class="field full-width">Or upload CSV<input type="file" name="statement_csv" accept=".csv,text/csv"></label></div><p class="muted small">Balances can be negative for an overdraft. Statement amounts must be in <?= pl_e($company['currency']) ?>. XLSX and bank-specific formats are not supported.</p><label><input type="checkbox" name="baseline_confirmed" value="1" <?= pl_web_text($input, 'baseline_confirmed') === '1' ? 'checked' : '' ?>> For the first statement, all earlier ledger entries for this account have cleared the bank and its opening balance agrees with the ledger. Resolve earlier outstanding items before starting.</label><p><button class="button primary">Preview statement</button></p></form></section><?php endif; ?>
        <section class="panel"><h2>Statement history</h2><?php if ($statements === []): ?><p>No statements imported yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><caption class="sr-only">Imported bank statements</caption><thead><tr><th>Statement</th><th>Bank account</th><th>Dates</th><th class="amount">Closing</th><th>Status</th></tr></thead><tbody><?php foreach ($statements as $item): ?><tr><td><a href="<?= pl_e(pl_url('/bank-reconciliation', ['id' => (int) $item['id']])) ?>"><?= pl_e($item['reference']) ?></a></td><td><?= pl_e($item['account_name']) ?></td><td><?= pl_e($item['start_date']) ?> – <?= pl_e($item['end_date']) ?></td><td class="amount"><?= pl_e(pl_money((string) $item['closing_balance'])) ?></td><td><?= pl_e(['draft' => 'In progress', 'completed' => 'Completed', 'cancelled' => 'Cancelled'][$item['status']]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if ($page > 1): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['page' => $page - 1])) ?>">Previous</a><?php endif; ?><?php if ($hasMore): ?><a class="button" href="<?= pl_e(pl_url('/bank-reconciliation', ['page' => $page + 1])) ?>">Next</a><?php endif; ?></section>
    <?php endif; ?>
</div>
